solution.code:
#include <stdio.h>

int missing(const int a[], int n) {
    int expected = n * (n + 1) / 2;
    int actual = 0;
    for (int i = 0; i < n; i++) {
        actual += a[i];
    }
    return expected - actual;
}

int main() {
    int a[] = {9, 6, 4, 2, 3, 5, 7, 0, 1};
    printf("%d\n", missing(a, 9));
    return 0;
}
